using System;using System.Drawing;using System.Drawing.Imaging;using System.Drawing.Drawing2D;using System.IO;using System.Runtime.InteropServices;using System.Text;
internal static partial class BackgroundEffects{
 internal static string RegionColor(EffectSettings s,int region){return region==0?s.ListColor??s.Color:region==2?s.InputColor??s.Color:region==4?s.NavigationColor??s.Color:s.Color;}
 internal static int RegionBlur(EffectSettings s,int region){return region==0?s.ListBlur:region==2?s.InputBlur:region==4?s.NavigationBlur:0;}
 internal static Bitmap Frost(Image source,int pixels,int maxWidth=1600){double scale=Math.Min(1,maxWidth/(double)source.Width);var result=new Bitmap(Math.Max(1,(int)Math.Round(source.Width*scale)),Math.Max(1,(int)Math.Round(source.Height*scale)),PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(result)){g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.DrawImage(source,0,0,result.Width,result.Height);}if(pixels==0)return result;var area=new Rectangle(0,0,result.Width,result.Height);var data=result.LockBits(area,ImageLockMode.ReadWrite,PixelFormat.Format32bppArgb);try{var bytes=new byte[data.Stride*data.Height];var temp=new byte[bytes.Length];Marshal.Copy(data.Scan0,bytes,0,bytes.Length);int radius=Math.Max(1,(int)Math.Round(pixels*result.Width/1600d));for(int i=0;i<3;i++){Box(bytes,temp,result.Width,result.Height,radius,true);Box(temp,bytes,result.Width,result.Height,radius,false);}Marshal.Copy(bytes,0,data.Scan0,bytes.Length);}finally{result.UnlockBits(data);}return result;}
 internal static string PrepareFrost(string processed,int pixels){if(pixels<=0)return "";string dir=Path.Combine(Engine.Store,"effects-cache");Directory.CreateDirectory(dir);string path=Path.Combine(dir,"region-"+Engine.Hash(Encoding.UTF8.GetBytes(Engine.Hash(File.ReadAllBytes(processed))+"|"+pixels))+".png");if(!File.Exists(path))using(var source=Image.FromFile(processed))using(var image=Frost(source,pixels))image.Save(path,ImageFormat.Png);return path;}
 internal static void DrawFrost(Graphics g,Image frost,RectangleF region,SizeF root){if(frost==null)return;var state=g.Save();g.SetClip(region,CombineMode.Intersect);float scale=Math.Max(root.Width/frost.Width,root.Height/frost.Height),w=frost.Width*scale,h=frost.Height*scale;g.DrawImage(frost,(root.Width-w)/2,(root.Height-h)/2,w,h);g.Restore(state);}
}
internal sealed class WallpaperLayerCache:IDisposable{
 Image original;readonly Bitmap[] images=new Bitmap[5];readonly int[] strengths=new int[5];
 internal void Draw(Graphics g,Image wallpaper,EffectSettings settings,RectangleF bounds,SizeF root,int region){if(wallpaper==null)return;if(!Object.ReferenceEquals(original,wallpaper)){Dispose();original=wallpaper;}int blur=BackgroundEffects.RegionBlur(settings,region);if(blur<=0)return;if(images[region]==null||strengths[region]!=blur){if(images[region]!=null)images[region].Dispose();images[region]=BackgroundEffects.Frost(wallpaper,blur,1000);strengths[region]=blur;}BackgroundEffects.DrawFrost(g,images[region],bounds,root);}
 public void Dispose(){for(int i=0;i<images.Length;i++)if(images[i]!=null){images[i].Dispose();images[i]=null;}original=null;}
}
